export type SessionState = "Running" | { Idle: {
	stop_reason: StopReason | null,
} } | "RequiresAction";

/**  Outcome of an optional worktree setup script. */
export type SetupOutcome = {
	exit_code: number | null,
	stderr: string,
	timed_out: boolean,
};

/**  Where `skills.import` should load from. */
export type SkillImportSource = { kind: "folder"; path: string } | { kind: "archive"; path: string } | { kind: "git-hub"; spec: string };

/**  One skill in the canonical home. */
export type SkillInfo = {
	name: string,
	scope: Scope,
	path: string,
	source: SkillSource,
	enabled: boolean,
	requires_trust: boolean,
	trusted: boolean,
	content_hash: string,
	pinned_sha?: string | null,
};

/**  Where a skill came from. */
export type SkillOrigin = "folder" | "archive" | "git-hub" | "lockfile";

/**  Skill provenance (`skills_state.source` JSON). */
export type SkillSource = {
	origin: SkillOrigin,
	repo?: string | null,
	reference?: string | null,
	subdir?: string | null,
	lock_hash?: string | null,
	url?: string | null,
};

/**  Result of applying one skill update. */
export type SkillUpdateApplied = {
	name: string,
	pinned_sha: string,
	content_hash: string,
};

/**  Cheap upstream check for one skill. */
export type SkillUpdateCheck = {
	name: string,
	pinned_sha?: string | null,
	upstream_sha?: string | null,
	update_available: boolean,
	error?: string | null,
};

/**  Download-and-diff preview for one skill update. */
export type SkillUpdatePlan = {
	name: string,
	upstream_sha: string,
	changed_files: string[],
	diff: string,
};

export type StateChanged = {
	state: SessionState,
};

export type StopReason = "EndTurn" | "MaxTokens" | "MaxTurnRequests" | "StopSequence" | "Refusal" | "Cancelled" | "Error" | { Other: string };

/**  An immutable event stored in the append-only event log. */
export type StoredEvent = {
	id: number,
	thread_id: ThreadId,
	seq: number,
	event_type: string,
	payload: string,
	created_at: number,
};

/**  A chunk emitted over Tauri IPC streaming channels (S0.1). */
export type StreamChunk = {
	stream_id: number,
	seq: number,
	timestamp_ms: number | null,
	payload: string,
};

/**  A file surface or session that a registry entry can be projected to (legacy). */
export type TargetId = "session" | "claude-code" | "codex" | "open-code";

/**  Stable thread identifier. */
export type ThreadId = string;

/**  UI-02 thread states. */
export type ThreadState = "Idle" | "Running" | "AwaitingApproval" | "Error" | "Interrupted" | "Suspended" | "Archived";

/**  Thread row returned by `thread.create/list/get`. */
export type ThreadSummary = {
	id: ThreadId,
	workspace_id: string,
	agent_profile_id: string,
	title: string,
	workdir: string,
	state: ThreadState,
	session_id: string | null,
};

/**  Result of opening a thread, containing materialized entries and tail sequence. */
export type ThreadView = {
	entries: Entry[],
	latest_seq: number,
	has_more: boolean,
};

export type ToolCallContent = ({ Text: string }) & { Diff?: never; Terminal?: never; Unknown?: never } | ({ Diff: {
	path: string,
	patch: string,
} }) & { Terminal?: never; Text?: never; Unknown?: never } | ({ Terminal: {
	terminal_id: string,
} }) & { Diff?: never; Text?: never; Unknown?: never } | ({ Unknown: string }) & { Diff?: never; Terminal?: never; Text?: never };

export type ToolCallPatch = {
	title: string | null,
	kind: ToolKind | null,
	status: ToolCallStatus | null,
	input: string | null,
	output: string | null,
	origin?: ToolOrigin | null,
	parent_tool_call_id?: string | null,
	locations?: ToolLocation[],
};

export type ToolCallStatus = "Pending" | "Executing" | "Completed" | "Failed";

/**
 *  Closed ACP tool taxonomy, plus an open `Other` fallback.
 * 
 *  Wire spellings are ACP's snake_case (`read`, `edit`, …, `other`), which is
 *  what the v1 mapper already emitted as a bare string before this type landed.
 */
export type ToolKind = "read" | "edit" | "delete" | "move" | "search" | "execute" | "think" | "fetch" | "switch_mode" | "other";

/**
 *  A file location a tool call touched. Deserializes from either the new
 *  `{ path, line }` object or the legacy bare path string.
 */
export type ToolLocation = {
	path: string,
	line: number | null,
};

/**
 *  Where a tool call came from. Populated by Provider adapters (Wave 2.5);
 *  no code in M1.6c sets it, and an entry with no `origin` is a built-in call.
 */
export type ToolOrigin = { kind: "builtin" } | { kind: "mcp"; server: string } | { kind: "skill"; name: string } | { kind: "subagent" };

/**  MCP transport of a registry entry. */
export type TransportKind = "stdio" | "http" | "sse";

/**
 *  The `workspace.add` request — the one path-taking method, because it *is*
 *  the trust flow (`architecture.md` §1 principle 8's stated exception).
 */
export type TrustGrant = {
	/**  The folder the user picked; Core canonicalizes it before trusting. */
	path: string,
	permission_mode: PermissionMode,
	scope: TrustScope,
	/**  Run `git init` in place when the folder is not a repository. */
	init_git?: boolean,
};

/**  Scope a trust grant covers (`pages-views-spec.md` §2.1). */
export type TrustScope = "folder" | "subtree";

/**  Normalized event model (architecture §7.3). One v2-shaped stream for all agents. */
export type TurnEventBody = { type: "StateChanged"; body: StateChanged } | { type: "MessageUpsert"; body: MessageUpsert } | { type: "MessageChunk"; body: MessageChunk } | { type: "ToolCallUpsert"; body: {
	tool_call_id: string,
	patch: ToolCallPatch,
} } | { type: "ToolCallContentChunk"; body: {
	tool_call_id: string,
	item: ToolCallContent,
} } | { type: "TerminalUpsert"; body: {
	terminal_id: string,
	patch: Patch<string>,
} } | { type: "TerminalOutputChunk"; body: {
	terminal_id: string,
	bytes: string,
} } | { type: "PlanUpsert"; body: {
	plan_id: string,
	plan: PlanContent,
} } | { type: "ConfigOptionsChanged"; body: {
	options: ConfigOption[],
} } | { type: "CommandsAvailable"; body: {
	commands: AgentCommand[],
} } | { type: "SessionInfo"; body: SessionInfo } | { type: "Usage"; body: {
	snapshot: UsageSnapshot,
} } | { type: "PermissionRequested"; body: PermissionRequested } | { type: "PermissionResolved"; body: {
	req_id: string,
	outcome: PermOutcome,
	decided_by: Decider,
	/**
	 *  The Provider's option that was chosen, when one was. Append-only
	 *  field (M1.7) so a resolved card can name the auto-picked option.
	 */
	option_id?: string | null,
} } | { type: "FileWrite"; body: {
	path: string,
	before: string | null,
	after: string,
	via: WriteVia,
} } | { type: "Checkpoint"; body: {
	oid: string,
	kind: CheckpointKind,
} } | { type: "Error"; body: {
	code: string,
	message: string,
	retryable: boolean,
} } | { type: "Unknown"; body: {
	raw: string,
} } | 
/**
 *  A vendor-extension request (`_`-prefixed ACP method). Appended last, an
 *  append-only region; transport is M1.17.
 */
{ type: "ProviderExtension"; body: ProviderExtension } | 
/**  A Provider's context-compaction notice (unstable ACP `compaction_update`). */
{ type: "Compaction"; body: {
	summary: string | null,
} } | 
/**
 *  An elicitation request (`elicitation/create`). Appended last, an
 *  append-only region (M1.7).
 */
{ type: "ElicitationRequested"; body: ElicitationRequest } | 
/**  The user's answer to an elicitation. Appended last (M1.7). */
{ type: "ElicitationResolved"; body: {
	req_id: string,
	outcome: ElicitationOutcome,
	values: { [key in string]: ElicitationValue },
} } | 
/**
 *  A cancel-ladder phase transition (`cancel_requested` → `grace_elapsed` →
 *  `terminating`, or back to `idle`). Appended last, an append-only region;
 *  emitted by M1.12's Stop backend and read by the `Stop` control. The
 *  backend owns the clock, so the payload carries the absolute deadline.
 */
{ type: "CancelPhaseChanged"; body: CancelState };

/**  Refs holding the pre-restore state so restore is itself reversible. */
export type UndoCapture = {
	worktree_ref: string,
	index_ref: string,
	worktree_tree: string,
	index_tree: string,
};

/**  Whether an upstream release is newer than a profile's pin. */
export type UpdateAvailability = { kind: "up-to-date" } | { kind: "available"; latest: string };

export type UsageSnapshot = {
	input_tokens: number,
	output_tokens: number,
	/**
	 *  Tokens currently in context: the v1 mapper stores ACP's `used` here and
	 *  leaves `input_tokens` / `output_tokens` at 0 (see `tethys-acp` `map.rs`).
	 */
	total_tokens: number,
	cost: number | null,
	context_size?: number | null,
	cost_currency?: string | null,
};

/**  Version control state of a workspace root. */
export type Vcs = 
/**  Not a git repository. */
{ kind: "none" } | 
/**  A git repository with no remote configured. */
{ kind: "git-local" } | 
/**  A git repository with a remote; `host` drives the source badge. */
{ kind: "git-remote"; host: GitHost };

/**  Result of verifying a projected file against its manifest entry. */
export type VerifyStatus = "in-sync" | "drifted" | "missing";

/**  Resolved capabilities for one workspace. */
export type WorkspaceCapabilities = {
	/**  Version control the folder is under, and the remote host if any. */
	vcs: Vcs,
	/**  Checkpoints exist and the session can restore them. */
	restore: boolean,
	/**  `Some(1)` where no worktree mechanism isolates parallel sessions. */
	max_concurrent_sessions: number | null,
};

/**  Per-project git settings loaded from `<repo>/.tethys/config.json`. */
export type WorkspaceGitConfig = {
	/**  Override for the default `~/.tethys/worktrees/<repo-id>/<slug>` location. */
	worktrees_dir?: string | null,
	/**  Branch template for new thread worktrees; `{slug}` is substituted. */
	wt_branch_template?: string,
	/**  Untracked/ignored globs copied from the main worktree (default `.env*`). */
	bootstrap_globs?: string[],
	/**  Untracked binaries larger than this are skipped by checkpoints. */
	skip_untracked_binary_bytes?: number,
	/**  Timeout for the optional worktree setup script. */
	setup_timeout_ms?: number,
};

/**  Stable workspace identifier. */
export type WorkspaceId = string;

/**  One catalog card: a trusted, addressable workspace. */
export type WorkspaceListItem = {
	id: WorkspaceId,
	name: string,
	path: string,
	capabilities: WorkspaceCapabilities,
	trust: WorkspaceTrustState,
	sessions: WorkspaceSessionSummary[],
};

/**
 *  A live thread attached to a card. Branch, turn and diff are the session
 *  surface's view (fixture-backed until the checkpoint, D12); this carries the
 *  trustworthy identity and state.
 */
export type WorkspaceSessionSummary = {
	id: string,
	title: string,
	state: ThreadState,
};

/**  Whether a workspace's stored trust decision still matches its folder. */
export type WorkspaceTrustState = 
/**  A live trust row whose resolved path and remote still match. */
"trusted" | 
/**  No trust row: never added or revoked. */
"untrusted" | 
/**  Trusted once, but the resolved path or remote changed (re-prompt). */
"changed";

/**  Result of materializing a worktree. */
export type WorktreeInfo = {
	thread_id: string,
	workspace_root: string,
	path: string,
	branch: string,
	base: string,
	head: string,
	main_checkout: boolean,
	warnings: string[],
	setup: SetupOutcome | null,
};

/**  Everything the engine needs to materialize a thread worktree. */
export type WorktreeSpec = {
	thread_id: string,
	/**  Workspace ID whose root is resolved in Core. */
	workspace_id: WorkspaceId,
	/**  URL-safe thread slug used for paths and default branch names. */
	slug: string,
	/**  Worktree path; empty means "derive from `worktrees_dir`". */
	path: string,
	/**  Branch to create; empty means "apply the configured template". */
	branch: string,
	/**  Commit-ish the branch starts from. */
	base: string,
	/**  Ignored-file globs copied into the new worktree. */
	bootstrap_globs: string[],
	/**  Optional synchronization script run inside the new worktree. */
	setup_script: string | null,
	/**  When true, register the existing checkout instead of creating a worktree. */
	main_checkout: boolean,
};

export type WriteVia = "AcpFs" | "Watcher";
